export const foundationInputNumber = value => {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string" || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim())) return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};

export const foundationPositiveWholeNumber = value => {
  const number = foundationInputNumber(value);
  const whole = typeof value !== "string" || /^[+-]?\d+(?:\.0*)?$/.test(value.trim());
  return whole && Number.isSafeInteger(number) && number > 0;
};

export function foundationGeometryValidation(item, index = 0) {
  const record = item ?? {};
  const issues = [];
  const add = (field, code, message) => issues.push({
    kind: "foundation", index, componentId: record.component_id ?? null, field, code,
    message: `Foundation ${index + 1}: ${message}`,
  });
  const type = record.foundation_type;
  if (type !== "spread_foot" && type !== "pillar") {
    add("foundation_type", "foundation_type_invalid", "select Spread Footing or Pillar / Caisson.");
  }
  const count = record.quantity ?? 1;
  const quantity = foundationInputNumber(count);
  if (!foundationPositiveWholeNumber(count)) {
    add("quantity", "foundation_quantity_invalid", "quantity must be a positive whole number within the supported range.");
  }
  const fields = type === "spread_foot"
    ? [["length_inches", "length"], ["width_inches", "width"], ["depth_inches", "depth"]]
    : type === "pillar" ? [["diameter", "diameter"], ["depth_inches", "depth"]] : [];
  const dimensions = {};
  for (const [field, label] of fields) {
    const value = foundationInputNumber(record[field]);
    dimensions[field] = value;
    if (value === null || value <= 0) {
      add(field, "foundation_dimension_invalid", `${label} (inches) must be a finite positive number.`);
    }
  }
  if (!issues.length) {
    const depth = dimensions.depth_inches / 12;
    const radius = dimensions.diameter / 24;
    const volume = type === "spread_foot"
      ? ((dimensions.length_inches / 12) * (dimensions.width_inches / 12) * depth) / 27 * quantity
      : (Math.PI * radius * radius * depth) / 27 * quantity;
    // This is numeric-range validation, not a structural design or engineering minimum.
    if (!Number.isFinite(volume) || volume <= 0) {
      add("dimensions", "foundation_volume_out_of_range", "dimensions and quantity cannot produce a finite positive volume in the supported calculation range.");
    }
  }
  return { issues, type, quantity, dimensions };
}

export function foundationItemGeometryIssues(item, index = 0) {
  return foundationGeometryValidation(item, index).issues;
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { inventoryDraftInput } from "@/components/masterInventory/inventoryNormalization";
import { Trash2, Plus } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import {
  POLE_SHAPE_VALUES,
  consolidateFoundationPoles,
} from "./poleCalculator";

// Blank-preserving project-entry draft, delegated to the boundary (CMP-A08).
const heightInput = inventoryDraftInput;

// CMP-E01/O-056: the project-level poles list below is the single priced
// representation. Items can still carry pre-consolidation pole fields; they
// surface here as an advisory (never priced — no double charge) and move onto
// the canonical list only through the explicit onMigrateItemPole callback.
// CMP-E02/O-057: the inputs keep the five distinct quantities separate —
// height above grade, embedment below grade (canonical `embedment_inches`;
// a legacy row's `y_offset_inches` migrates into it on edit), vertical base
// offset, and explicit total stock length — with the actual shape carried on
// `pole_shape`.
export default function FoundationPolesPanel({ poles = [], options = [], items = [], onChange, polePricing = [], onMigrateItemPole }) {
  const patchPole = (index, changes) =>
    onChange(poles.map((p, i) => (i === index ? { ...p, ...changes } : p)));

  const removePole = (index) => {
    if (!window.confirm(`Remove Pole ${index + 1}? Cabinets mounted on it are retained for review.`)) return;
    onChange(poles.filter((_, i) => i !== index));
  };

  const addPole = () =>
    onChange([
      ...poles,
      { pole_id: options[0]?.id || "", height_inches: 120, embedment_inches: 42, include_pole_painting: false },
    ]);

  // Legacy item-pole fields ride on the items; they are advisory-only and
  // never part of the priced list this panel edits.
  const consolidated = consolidateFoundationPoles({ items, poles });

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Poles</h2>
          <p className="text-xs text-gray-500">
            Priced on billed length — an explicit total stock length, or height above grade plus embedment.
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={addPole} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Pole
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Pole catalog unavailable — existing rows remain editable; new poles cannot be added.
        </div>
      )}
      {consolidated.legacyPoles.length > 0 && (
        <div role="status" className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5 space-y-1">
          <p className="font-semibold">Legacy item-pole data — not priced</p>
          {consolidated.legacyPoles.map((d) => (
            <div key={d.source_item_component_id || `item-${d.source_item_index}`} className="flex items-center justify-between gap-2">
              <span>
                Foundation {d.source_item_index + 1} carries legacy pole fields
                {d.legacy_pole_cost !== null || d.legacy_pole_painting_cost !== null ? " (with saved amounts)" : ""}.
              </span>
              {typeof onMigrateItemPole === "function" && (
                <Button variant="outline" size="sm" onClick={() => onMigrateItemPole(d.source_item_index)}>
                  Move to Poles
                </Button>
              )}
            </div>
          ))}
          {consolidated.overlaps.length > 0 && (
            <p>A project pole already sits on the same foundation — verify it is not the same physical pole before migrating.</p>
          )}
        </div>
      )}
      {poles.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No poles on this section.
        </div>
      ) : (
        poles.map((pole, index) => {
          const issues = polePricing[index]?.issues || [];
          const pricingUnavailable = polePricing[index]?.available === false;
          const geometry = polePricing[index]?.geometry || null;
          const fieldIssue = (field) => issues.some((i) => i.field === field);
          const describedBy = issues.length ? `pole-${index}-pricing` : undefined;
          const authoredShape = pole.pole_shape ?? "";
          const shapeChoices = authoredShape && !POLE_SHAPE_VALUES.includes(authoredShape)
            ? [authoredShape, ...POLE_SHAPE_VALUES]
            : POLE_SHAPE_VALUES;
          return (
            <div key={pole.component_id || index} className="bg-white rounded-xl border border-gray-200 p-3">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2 items-end">
                <label className="text-xs text-gray-500 md:col-span-2">
                  Pole
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.pole_id || ""}
                    aria-label="Pole material"
                    aria-invalid={fieldIssue("pole_id") || undefined}
                    aria-describedby={fieldIssue("pole_id") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_id: e.target.value })}
                  >
                    <option value="">Select pole…</option>
                    {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                      <option value={pole.pole_id} disabled>{`Catalog pole unavailable (${pole.pole_id})`}</option>
                    )}
                    {options.map((o) => (
                      <option key={o.id} value={o.id}>
                        {o.material_name}
                      </option>
                    ))}
                  </select>
                  {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                    <span className="block text-[10px] text-amber-700 mt-1">Catalog pole unavailable; current pricing needs review.</span>
                  )}
                </label>
                <label className="text-xs text-gray-500">
                  Shape
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={authoredShape}
                    aria-label={`Pole ${index + 1} cross-section shape`}
                    aria-invalid={fieldIssue("pole_shape") || undefined}
                    aria-describedby={fieldIssue("pole_shape") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_shape: e.target.value === "" ? undefined : e.target.value })}
                  >
                    <option value="">Catalog / unspecified</option>
                    {shapeChoices.map((s) => (
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-500">
                  Foundation
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.foundation_component_id ?? ""}
                    aria-label="Pole foundation"
                    onChange={(e) => {
                      const id = e.target.value;
                      const i = items.findIndex((it) => it.component_id === id);
                      patchPole(index, {
                        foundation_component_id: id,
                        foundation_idx: id === "" || i < 0 ? undefined : i,
                      });
                    }}
                  >
                    <option value="">Unassigned</option>
                    {pole.foundation_component_id && !items.some((it) => it.component_id === pole.foundation_component_id) && (
                      <option value={pole.foundation_component_id} disabled>{`Missing foundation (${String(pole.foundation_component_id).slice(0, 18)}…)`}</option>
                    )}
                    {items.map((it, i) => (
                      <option key={it.component_id || i} value={it.component_id || ""}>
                        {it.description || `Foundation ${i + 1}`}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-500">
                  Height above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.height_inches ?? ""}
                    aria-label={`Pole ${index + 1} height above grade (inches)`}
                    aria-invalid={fieldIssue("height_inches") || undefined}
                    aria-describedby={fieldIssue("height_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { height_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Embedment below grade (in)
                  <Input
                    type="number"
                    step="any"
                    // A recorded canonical value wins; blank canonical falls
                    // back to the legacy spelling so display matches pricing.
                    value={(pole.embedment_inches !== undefined && pole.embedment_inches !== null && pole.embedment_inches !== "")
                      ? pole.embedment_inches
                      : (pole.y_offset_inches ?? "")}
                    aria-label={`Pole ${index + 1} embedment below grade (inches)`}
                    aria-invalid={fieldIssue("embedment_inches") || fieldIssue("y_offset_inches") || undefined}
                    aria-describedby={(fieldIssue("embedment_inches") || fieldIssue("y_offset_inches")) ? describedBy : undefined}
                    onChange={(e) => patchPole(index, {
                      // Canonical field carries the edit; the legacy spelling
                      // clears so the two can never diverge into a conflict.
                      embedment_inches: heightInput(e.target.value),
                      y_offset_inches: undefined,
                    })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Base offset above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.base_offset_inches ?? ""}
                    aria-label={`Pole ${index + 1} base offset above grade (inches)`}
                    aria-invalid={fieldIssue("base_offset_inches") || undefined}
                    aria-describedby={fieldIssue("base_offset_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { base_offset_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Total stock length (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.total_length_inches ?? ""}
                    aria-label={`Pole ${index + 1} total stock length (inches)`}
                    aria-invalid={fieldIssue("total_length_inches") || undefined}
                    aria-describedby={fieldIssue("total_length_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { total_length_inches: heightInput(e.target.value) })}
                  />
                </label>
              </div>

              <div className="flex items-center justify-between mt-2">
                <label className="flex items-center gap-1.5 text-xs font-medium text-gray-700">
                  <input
                    type="checkbox"
                    checked={!!pole.include_pole_painting}
                    aria-invalid={issues.some((i) => i.code === "pole_paint_setting_unavailable") || undefined}
                    aria-describedby={issues.some((i) => i.code === "pole_paint_setting_unavailable") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { include_pole_painting: e.target.checked })}
                  />
                  Paint pole
                </label>
                <div className="flex items-center gap-3 text-xs text-gray-600">
                  {geometry && Number.isFinite(geometry.required_length_inches) && (
                    <span title={`Required ${geometry.required_length_inches} in${Number.isFinite(pole.stock_pieces) ? ` · ${pole.stock_pieces} stock ${pole.stock_pieces === 1 ? "piece" : "pieces"}` : ""}${geometry.pole_shape ? ` · ${geometry.pole_shape}` : ""}${geometry.base_offset_inches > 0 ? ` · base +${geometry.base_offset_inches} in` : ""}`}>
                      {geometry.required_length_inches} in req
                    </span>
                  )}
                  <span>Pole {hasFoundationCostSnapshot(pole.pole_cost) ? money(pole.pole_cost) : "Not saved"}</span>
                  <span>Paint {hasFoundationCostSnapshot(pole.pole_painting_cost) ? money(pole.pole_painting_cost) : "Not saved"}</span>
                  <span className="font-bold text-gray-900 text-sm">{hasFoundationCostSnapshot(pole.total_cost) ? money(pole.total_cost) : "Not saved"}</span>
                  {pricingUnavailable && <span className="col-span-full text-[10px] text-amber-700">Saved amounts (not current pricing)</span>}
                  <Button variant="ghost" size="icon" onClick={() => removePole(index)}>
                    <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                  </Button>
                </div>
              </div>
              {issues.length > 0 && (
                <div role="status" className="mt-2 text-[10px] text-amber-700 space-y-0.5" id={`pole-${index}-pricing`}>
                  {issues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
                </div>
              )}
            </div>
          );
        })
      )}
    </div>
  );
}

import React from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus, PenLine } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallPricingIssues } from "./wallCalculator";
import { inventoryDraftInput } from "@/components/masterInventory/inventoryNormalization";
import WallShapeEditor from "./WallShapeEditor";

// Blank-preserving project-entry draft, delegated to the boundary (CMP-A08).
const heightInput = inventoryDraftInput;

function WallRow({ wall, index, options, pricing, onChange, onRemove }) {
  const c = wall.calculatedCosts || {};
  const set = (changes) => onChange(index, changes);
  // Settings-aware issues arrive from calcProject; the local re-derive covers
  // consumers that cannot supply them (no settings visibility).
  const pricingIssues = pricing?.issues ?? foundationWallPricingIssues(wall, options, index);
  const pricingUnavailable = pricing?.available === false || pricingIssues.length > 0;
  const amt = (v) => (hasFoundationCostSnapshot(v) ? money(v) : "Not saved");
  const [showEditor, setShowEditor] = React.useState(false);
  const fieldIssue = (field) => pricingIssues.some((i) => i.field === field);
  const describedBy = (field) => (fieldIssue(field) ? `wall-${index}-pricing` : undefined);

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-3 space-y-3">
      <div className="flex items-center justify-between gap-2">
        <Input
          className="min-w-0 max-w-[220px]"
          value={wall.name || ""}
          placeholder={`Wall ${index + 1}`}
          onChange={(e) => set({ name: e.target.value })}
        />
        <div className="flex shrink-0 items-center gap-3">
          <span className="whitespace-nowrap font-bold text-gray-900">{amt(c.totalCost)}</span>
          <Button variant="ghost" size="icon" onClick={() => onRemove(index)}>
            <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <label className="text-xs text-gray-500">
          Height (in)
          <Input
            type="number"
            step="any"
            value={wall.heightInches ?? ""}
            onChange={(e) => set({ heightInches: heightInput(e.target.value) })}
            aria-label="Wall height (in)"
            aria-invalid={fieldIssue("heightInches") || undefined}
            aria-describedby={describedBy("heightInches")}
          />
        </label>
        <label className="text-xs text-gray-500">
          Mortar gap (in)
          <Input
            type="number"
            step="0.125"
            min="0"
            value={wall.mortarGapInches ?? 0.375}
            placeholder="0.375"
            onChange={(e) => set({ mortarGapInches: heightInput(e.target.value) })}
            aria-label="Wall mortar gap (in)"
            aria-invalid={fieldIssue("mortarGapInches") || undefined}
            aria-describedby={describedBy("mortarGapInches")}
          />
        </label>
        <label className="text-xs text-gray-500 md:col-span-2">
          Wall material
          <select
            className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
            value={wall.materialId || ""}
            aria-label="Wall material"
            aria-invalid={fieldIssue("materialId") || undefined}
            aria-describedby={describedBy("materialId")}
            onChange={(e) => set({ materialId: e.target.value })}
          >
            <option value="">Select material…</option>
            {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
              <option value={wall.materialId} disabled>{`Catalog material unavailable (${wall.materialId})`}</option>
            )}
            {options.map((o) => (
              <option key={o.id} value={o.id}>
                {o.material_name}
              </option>
            ))}
          </select>
          {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
            <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
          )}
        </label>
      </div>

      <div className="rounded-lg bg-slate-50 p-2 space-y-2">
        <label className="flex items-center gap-2 text-xs font-medium text-gray-700">
          <input
            type="checkbox"
            checked={!!wall.includeInternalWall}
            onChange={(e) => set({ includeInternalWall: e.target.checked })}
          />
          Internal fill wall
        </label>
        {wall.includeInternalWall && (
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            <label className="text-xs text-gray-500 md:col-span-2">
              Fill material
              <select
                className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                value={wall.internalMaterialId || ""}
                aria-label="Internal wall material"
                aria-invalid={fieldIssue("internalMaterialId") || undefined}
                aria-describedby={describedBy("internalMaterialId")}
                onChange={(e) => set({ internalMaterialId: e.target.value })}
              >
                <option value="">Select material…</option>
                {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                  <option value={wall.internalMaterialId} disabled>{`Catalog material unavailable (${wall.internalMaterialId})`}</option>
                )}
                {options.map((o) => (
                  <option key={o.id} value={o.id}>
                    {o.material_name}
                  </option>
                ))}
              </select>
              {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
              )}
            </label>
            <label className="text-xs text-gray-500">
              Fill height (in)
              <Input
                type="number"
                step="any"
                value={wall.internalWallHeightInches ?? wall.heightInches ?? ""}
                onChange={(e) => set({ internalWallHeightInches: heightInput(e.target.value) })}
                aria-label="Internal wall height (in)"
                aria-invalid={fieldIssue("internalWallHeightInches") || undefined}
                aria-describedby={describedBy("internalWallHeightInches")}
              />
            </label>
            <label className="text-xs text-gray-500">
              Fill mortar gap (in)
              <Input
                type="number"
                step="0.125"
                min="0"
                value={wall.internalMortarGapInches ?? 0.375}
                placeholder="0.375"
                onChange={(e) => set({ internalMortarGapInches: heightInput(e.target.value) })}
                aria-label="Internal wall mortar gap (in)"
                aria-invalid={fieldIssue("internalMortarGapInches") || undefined}
                aria-describedby={describedBy("internalMortarGapInches")}
              />
            </label>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs text-gray-600">
        {/* CMP-D03: the snapshot carries its quantity basis — poured concrete
            reads placed volume in CY (never "Units"), unit masonry keeps the
            unit count. Held rows keep whatever basis the acknowledged
            snapshot recorded. */}
        {c.materialQuantityUnit === "cy" ? (
          <div>CY: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalBricks) ? c.totalBricks.toFixed(2) : "Not saved"}</span></div>
        ) : (
          <div>Units: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalBricks) ? Math.round(c.totalBricks) : "Not saved"}</span></div>
        )}
        <div>Courses: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.numCourses) ? Math.ceil(c.numCourses) : "Not saved"}</span></div>
        <div>Material: <span className="font-semibold text-gray-900">{amt(c.materialCost)}</span></div>
        <div>Mortar: <span className="font-semibold text-gray-900">{amt(c.mortarCost)}</span></div>
        <div>Labor: <span className="font-semibold text-gray-900">{amt(c.laborCost)}</span></div>
        <div>Labor hrs: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.laborHours) ? c.laborHours.toFixed(1) : "Not saved"}</span></div>
        <div>Linear in: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalLinearInches) ? Math.round(c.totalLinearInches) : "Not saved"}</span></div>
        {pricingUnavailable && <div className="col-span-full text-[10px] font-semibold text-amber-700">Saved amounts (not current pricing)</div>}
        {pricingIssues.length > 0 && (
          <div role="status" className="col-span-full text-[10px] text-amber-700 space-y-0.5" id={`wall-${index}-pricing`}>
            {pricingIssues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
          </div>
        )}
      </div>

      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={() => setShowEditor((v) => !v)}
          aria-expanded={showEditor}
          aria-invalid={fieldIssue("shape") || undefined}
          aria-describedby={describedBy("shape")}>
          <PenLine className="w-4 h-4" aria-hidden="true" /> {showEditor ? "Hide outline" : "Wall outline"}
        </Button>
        {fieldIssue("shape") ? (
          <span className="text-xs text-amber-600">
            Outline geometry needs repair before repricing - see diagnostics above.
          </span>
        ) : !wall.shape?.segments?.length ? (
          <span className="text-xs text-amber-600">
            No outline yet - draw the wall footprint before estimating quantities.
          </span>
        ) : null}
      </div>

      {showEditor && (
        <WallShapeEditor shape={wall.shape} onChange={(shape) => set({ shape })} />
      )}
    </div>
  );
}

export default function FoundationWallsPanel({ walls = [], options = [], onChange, wallPricing = [] }) {
  const patchWall = (index, changes) =>
    onChange(walls.map((w, i) => (i === index ? { ...w, ...changes } : w)));

